1	const PROCESSING_FEE = 5;
2	const FIRST_INSURANCE_SURCHARGE_RATE = 0.1;
3	const CURSE_SURCHARGE_RATE = 0.5;
4	const HIGH_ENCHANTMENT_SURCHARGE_RATE = 0.3;
5	const HIGH_ENCHANTMENT_THRESHOLD = 5;
6	
7	const COMPONENT_BASE_PREMIUM = 25;
8	const BLOCK_SIZE = 3;
9	const BLOCK_PREMIUM = 60;
10	
11	const BASE_PREMIUM: Record<string, number> = {
12	  sword: 100,
13	  amulet: 60,
14	  staff: 80,
15	  potion: 40,
16	  rune: COMPONENT_BASE_PREMIUM,
17	  moonstone: COMPONENT_BASE_PREMIUM,
18	};
19	
20	const COMPONENT_TYPES = new Set(["rune", "moonstone"]);
21	
22	type Item = { type: string; cursed?: boolean; enchantment?: number };
23	type Scenario = {
24	  customer: { yearsWithMHPCO: number };
25	  steps: Array<{ op: "quote"; items: Item[] }>;
26	};
27	
28	const countsByType = (items: Item[]): Map<string, number> =>
29	  items.reduce(
30	    (counts, item) => counts.set(item.type, (counts.get(item.type) ?? 0) + 1),
31	    new Map<string, number>(),
32	  );
33	
34	const groupBase = (type: string, count: number): number =>
35	  COMPONENT_TYPES.has(type) && count === BLOCK_SIZE
36	    ? BLOCK_PREMIUM
37	    : count * BASE_PREMIUM[type];
38	
39	const itemsBase = (items: Item[]): number => {
40	  let total = 0;
41	  for (const [type, count] of countsByType(items)) {
42	    total += groupBase(type, count);
43	  }
44	  return total;
45	};
46	
47	const itemSurcharge = (item: Item): number => {
48	  const base = BASE_PREMIUM[item.type];
49	  const curse = item.cursed ? base * CURSE_SURCHARGE_RATE : 0;
50	  const highEnch =
51	    (item.enchantment ?? 0) >= HIGH_ENCHANTMENT_THRESHOLD
52	      ? base * HIGH_ENCHANTMENT_SURCHARGE_RATE
53	      : 0;
54	  return curse + highEnch;
55	};
56	
57	const itemSurchargesTotal = (items: Item[]): number =>
58	  items.reduce((sum, item) => sum + itemSurcharge(item), 0);
59	
60	const roundUpInFavorOfInsurer = (amount: number): number =>
61	  Math.ceil(Math.round(amount * 1e6) / 1e6);
62	
63	const quotePremium = (items: Item[]): number => {
64	  const policyBase = itemsBase(items);
65	  const firstInsuranceSurcharge = policyBase * FIRST_INSURANCE_SURCHARGE_RATE;
66	  const itemSurcharges = itemSurchargesTotal(items);
67	  return roundUpInFavorOfInsurer(policyBase + itemSurcharges + firstInsuranceSurcharge + PROCESSING_FEE);
68	};
69	
70	export const runScenario = (scenario: unknown): unknown => ({
71	  results: (scenario as Scenario).steps.map((step) => ({
72	    premium: quotePremium(step.items),
73	  })),
74	});
